import sys
import math

class Task:
    def __init__(self):
        self.mod = 1_000_000_007

    def solve(self, sc, pw):
        n = sc.nextInt()
        dp0 = [[0] * (n + 1) for _ in range(n + 1)]
        dp1 = [[0] * (n + 1) for _ in range(n + 1)]

        def get(arr, i, j):
            if i >= len(arr) or j >= len(arr[0]):
                return 0
            return arr[i][j]

        for sum in range(2 * n, -1, -1):
            for i in range(n + 1):
                j = sum - i
                if j < 0 or j > i or (i == n and j == n):
                    continue
                if i == j:
                    dp0[i][j] = max(1 + get(dp1, i + 1, j), get(dp0, i + 1, j))
                elif i == n:
                    dp0[i][j] = max(1 + get(dp1, i, j + 1), get(dp0, i, j + 1))
                else:
                    v1 = (get(dp0, i + 1, j) + get(dp0, i, j + 1)) % self.mod
                    v2 = (1 + get(dp1, i + 1, j) + get(dp0, i, j + 1)) % self.mod
                    v3 = (1 + get(dp0, i + 1, j) + get(dp1, i, j + 1)) % self.mod
                    dp0[i][j] = max(v1, v2, v3)
                if i == j:
                    dp1[i][j] = get(dp0, i + 1, j)
                elif i == n:
                    dp1[i][j] = get(dp0, i, j + 1)
                else:
                    v1 = (get(dp0, i + 1, j) + get(dp0, i, j + 1)) % self.mod
                    dp1[i][j] = v1
        pw.write(str(dp0[0][0] % self.mod) + "\n")

class Scanner:
    def __init__(self, stream):
        self.stream = stream
        self.buffer = []
    def next(self):
        while not self.buffer:
            line = self.stream.readline()
            if not line:
                return None
            self.buffer = line.strip().split()
        return self.buffer.pop(0)
    def nextInt(self):
        return int(self.next())

def main():
    sc = Scanner(sys.stdin)
    class Pw:
        def __init__(self):
            self.output = []
        def write(self, s):
            self.output.append(s)
        def close(self):
            print(''.join(self.output), end='')
    pw = Pw()
    task = Task()
    task.solve(sc, pw)

if __name__ == "__main__":
    main()

